"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[453],{69126(e){e.exports=JSON.parse('{"tag":{"label":"reference","permalink":"/hi/tags/reference","allTagsPath":"/hi/tags","count":9,"items":[{"id":"reference/cli-flags","title":"CLI \u092b\u093c\u094d\u0932\u0948\u0917","description":"linux-cleanup \u0915\u093e \u0939\u0930 \u0915\u092e\u093e\u0902\u0921 \u0932\u093e\u0907\u0928 \u092b\u093c\u094d\u0932\u0948\u0917 \u2014 \u092e\u094b\u0921, \u0935\u093f\u0915\u0932\u094d\u092a, \u0909\u092a\u0928\u093e\u092e \u0914\u0930 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u2014 \u0939\u0930 \u090f\u0915 \u0915\u094d\u092f\u093e \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u0909\u0938\u0915\u093e \u092a\u0942\u0930\u093e \u0935\u093f\u0935\u0930\u0923 \u0915\u0939\u093e\u0901 \u0939\u0948\u0964","permalink":"/hi/reference/cli-flags"},{"id":"reference/output-paths","title":"\u0906\u0909\u091f\u092a\u0941\u091f \u092a\u0925","description":"linux-cleanup \u0905\u092a\u0928\u0947 \u0932\u0949\u0917, JSON \u0938\u0924\u094d\u0930 \u0930\u093f\u0915\u0949\u0930\u094d\u0921, \u0921\u0940\u092c\u0917 \u092c\u0902\u0921\u0932 \u0914\u0930 \u0915\u094d\u0930\u0948\u0936 \u092c\u0902\u0921\u0932 \u0915\u0939\u093e\u0901 \u0932\u093f\u0916\u0924\u093e \u0939\u0948 \u2014 \u0922\u093e\u0901\u091a\u093e, \u0939\u0930 \u0907\u0902\u0938\u094d\u091f\u0949\u0932 \u0915\u0947 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f, \u0930\u0916\u0928\u0947 \u0915\u0940 \u0905\u0935\u0927\u093f \u0914\u0930 \u0905\u0928\u0941\u092e\u0924\u093f\u092f\u093e\u0901\u0964","permalink":"/hi/reference/output-paths"},{"id":"reference/exit-codes","title":"\u090f\u0917\u094d\u091c\u093c\u093f\u091f \u0915\u094b\u0921","description":"linux-cleanup \u0915\u0947 \u0939\u0930 \u090f\u0917\u094d\u091c\u093c\u093f\u091f \u0915\u094b\u0921 \u0915\u093e \u092e\u0924\u0932\u092c, \u0915\u094c\u0928-\u0938\u0947 \u0905\u092a\u0928\u0947 \u0906\u092a \u0915\u094d\u0930\u0948\u0936 \u092c\u0902\u0921\u0932 \u092c\u0928\u093e\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0938\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f \u092f\u093e cron \u091c\u0949\u092c \u092e\u0947\u0902 \u0909\u0928\u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 \u0915\u0948\u0938\u0947 \u0936\u093e\u0916\u093e \u092c\u0928\u093e\u090f\u0901\u0964","permalink":"/hi/reference/exit-codes"},{"id":"reference/environment-variables","title":"\u090f\u0928\u0935\u093e\u092f\u0930\u0928\u092e\u0947\u0902\u091f \u0935\u0947\u0930\u093f\u090f\u092c\u0932","description":"linux-cleanup \u091c\u094b \u092d\u0940 \u090f\u0928\u0935\u093e\u092f\u0930\u0928\u092e\u0947\u0902\u091f \u0935\u0947\u0930\u093f\u090f\u092c\u0932 \u092a\u0922\u093c\u0924\u093e \u0939\u0948, \u0909\u0928\u0915\u0947 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u0914\u0930 \u0905\u0938\u0930 \u2014 \u0906\u0909\u091f\u092a\u0941\u091f \u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u092c\u0926\u0932\u0928\u093e, \u0930\u0902\u0917 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0914\u0930 XDG \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917 \u0915\u0940 \u0916\u094b\u091c\u0964","permalink":"/hi/reference/environment-variables"},{"id":"reference/json-events","title":"\u092e\u0936\u0940\u0928 \u0938\u0947 \u092a\u0922\u093c\u0947 \u091c\u093e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0907\u0935\u0947\u0902\u091f","description":"\u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0938\u094d\u0915\u0948\u0928 \u0914\u0930 \u0917\u0948\u0930-\u0907\u0902\u091f\u0930\u0948\u0915\u094d\u091f\u093f\u0935 \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0928 \u0915\u0947 \u0932\u093f\u090f \u0938\u0902\u0938\u094d\u0915\u0930\u0923 1 \u0915\u0947 NDJSON \u0907\u0935\u0947\u0902\u091f\u0964","permalink":"/hi/reference/json-events"},{"id":"modes/overview","title":"\u092e\u094b\u0921 \u0915\u093e \u0938\u093e\u0930","description":"linux-cleanup \u0915\u0947 \u0938\u092d\u0940 \u092e\u094b\u0921, \u0915\u093e\u092e \u0915\u0947 \u0939\u093f\u0938\u093e\u092c \u0938\u0947 \u0938\u092e\u0942\u0939 \u092e\u0947\u0902 \u2014 \u0915\u0947\u0935\u0932-\u092a\u0922\u093c\u0928\u0947 \u0935\u093e\u0932\u0940 \u091c\u093e\u0901\u091a, \u0917\u093e\u0907\u0921\u0947\u0921 \u0914\u0930 \u092c\u0948\u091a \u0938\u092b\u093c\u093e\u0908, \u0907\u0902\u091f\u0930\u0948\u0915\u094d\u091f\u093f\u0935 \u0928\u093f\u091c\u0940-\u0921\u0947\u091f\u093e \u092e\u094b\u0921, \u0914\u0930 \u0906\u0909\u091f\u092a\u0941\u091f \u0935 \u0938\u0941\u0927\u093e\u0930 \u0915\u0947 \u0938\u0939\u093e\u092f\u0915\u0964","permalink":"/hi/modes/overview"},{"id":"reference/modes-matrix","title":"\u092e\u094b\u0921 \u0924\u093e\u0932\u093f\u0915\u093e","description":"linux-cleanup \u0915\u0947 \u0938\u092d\u0940 \u092e\u094b\u0921 \u090f\u0915 \u0938\u093e\u0925 \u2014 \u0915\u094c\u0928 \u0939\u091f\u093e\u0924\u093e \u0939\u0948, \u0915\u094c\u0928 \u0907\u0902\u091f\u0930\u0948\u0915\u094d\u091f\u093f\u0935 \u0939\u0948, \u0915\u094c\u0928 sudo \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930\u0924\u093e \u0939\u0948, \u0914\u0930 \u0915\u094c\u0928 \u0938\u0924\u094d\u0930 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0932\u093f\u0916\u0924\u093e \u0939\u0948\u0964","permalink":"/hi/reference/modes-matrix"},{"id":"reference/report-schema","title":"\u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0938\u094d\u0915\u0940\u092e\u093e","description":"linux-cleanup \u0915\u093e \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0924 \u0935\u0949\u0915\u0925\u094d\u0930\u0942 \u091c\u094b JSON \u0922\u093e\u0901\u091a\u093e \u0932\u093f\u0916\u0924\u093e \u0939\u0948 \u2014 credits, meta, disk, memory, steps \u0914\u0930 totals \u0915\u0947 \u0938\u093e\u0925\u0964","permalink":"/hi/reference/report-schema"},{"id":"reference/protected-paths","title":"\u0938\u0902\u0930\u0915\u094d\u0937\u093f\u0924 \u092a\u0925","description":"\u0909\u0928 \u092a\u0925\u094b\u0902 \u0915\u0940 \u092a\u0942\u0930\u0940, \u091c\u093e\u0901\u091a\u0940 \u0939\u0941\u0908 \u0938\u0942\u091a\u0940 \u091c\u093f\u0928\u094d\u0939\u0947\u0902 linux-cleanup \u0939\u091f\u093e\u0928\u0947 \u0938\u0947 \u092e\u0928\u093e \u0915\u0930\u0924\u093e \u0939\u0948 \u2014 \u0938\u093f\u0938\u094d\u091f\u092e \u0930\u0942\u091f, \u0928\u093f\u091c\u0940 \u092b\u093c\u094b\u0932\u094d\u0921\u0930, \u092a\u0948\u0915\u0947\u091c \u092e\u0948\u0928\u0947\u091c\u0930 \u0915\u0947 \u0907\u0902\u0938\u094d\u091f\u0949\u0932 \u0930\u0942\u091f \u0914\u0930 \u0936\u0947\u0932-\u0907\u0928\u093f\u091f \u092b\u093c\u093e\u0907\u0932 \u0928\u093e\u092e\u0964","permalink":"/hi/reference/protected-paths"}],"unlisted":false}}')}}]);